package com.aprax.aidesignstudio.activities;
import android.os.Bundle; import android.view.View; import android.widget.Button; import android.widget.Toast; import androidx.appcompat.app.AppCompatActivity; import com.aprax.aidesignstudio.R;
public class SettingsActivity extends AppCompatActivity implements View.OnClickListener { Button settingsBtn, refreshModelsBtn; public void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_app_settings); settingsBtn=findViewById(R.id.btn_settings); refreshModelsBtn=findViewById(R.id.refresh_models_button); if(settingsBtn!=null)settingsBtn.setOnClickListener(this); if(refreshModelsBtn!=null)refreshModelsBtn.setOnClickListener(this);} public void onClick(View v){Toast.makeText(this,"AI settings",Toast.LENGTH_SHORT).show();}}